# U5
def pie(cx,cy,r,n,k,c=RED,bg=WHITE):
    import math
    out=f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="{bg}" stroke="{INK}" stroke-width="3"/>'
    for i in range(n):
        a0=-math.pi/2+2*math.pi*i/n; a1=-math.pi/2+2*math.pi*(i+1)/n
        x0,y0=cx+r*math.cos(a0),cy+r*math.sin(a0); x1,y1=cx+r*math.cos(a1),cy+r*math.sin(a1)
        if i<k: out+=f'<path d="M{cx} {cy} L{x0:.1f} {y0:.1f} A{r} {r} 0 0 1 {x1:.1f} {y1:.1f} Z" fill="{c}"/>'
        out+=f'<line x1="{cx}" y1="{cy}" x2="{x0:.1f}" y2="{y0:.1f}" stroke="{INK}" stroke-width="2"/>'
    return out
